/**
 * Extension command handler — routes to subcommands.
 *
 * @module cli/commands/extension/handler
 */
import * as dntShim from "../../../_dnt.shims.js";
import { exitProcess, logSuccess, logUsageError } from "../../utils/index.js";
import { runExtensionInit, validateExtensionName } from "./init-command.js";
import { runExtensionValidate } from "./validate-command.js";
export async function handleExtensionCommand(args) {
    const subcommand = args._[1];
    switch (subcommand) {
        case "init": {
            const name = args._[2];
            if (!name) {
                logUsageError("Usage: veryfront extension init <name>");
                exitProcess(2);
                return;
            }
            const nameError = validateExtensionName(name);
            if (nameError) {
                logUsageError(nameError);
                exitProcess(2);
                return;
            }
            await runExtensionInit(name, dntShim.Deno.cwd());
            logSuccess(`Extension scaffolded at extensions/${name}/`);
            break;
        }
        case "validate": {
            const path = args._[2] || ".";
            await runExtensionValidate(path);
            break;
        }
        default:
            logUsageError("Usage: veryfront extension <init|validate> [args]");
            exitProcess(2);
    }
}
